            }
            Deque<Node> queue = new ArrayDeque<>();
            queue.offerLast(root);
            while (!queue.isEmpty()) {
                int size = queue.size();
                Node pre = null;
                for (int i = 0; i < size; i++) {
                    Node node = queue.pollFirst();
                    if (pre != null) {
                        pre.next = node;
                    }
                    if (node.left != null) {
                        queue.offerLast(node.left);
                    }
                    if (node.right != null) {
                        queue.offerLast(node.right);
                    }
                    pre = node;
                }
            }
